package reports;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.List;
import java.util.function.Supplier;

/**
 * The report demo. Given: do not edit this file. Run it from the starter folder with
 * mvn -q -o compile exec:java
 *
 * It creates an H2 database in memory, loads ../fixtures/orders.sql into it, prints each report,
 * and the database disappears when the program ends.
 */
public final class ReportApp {

    static final String URL = "jdbc:h2:mem:orders;INIT=RUNSCRIPT FROM '../fixtures/orders.sql'";

    private ReportApp() {
    }

    /** Prints one report line, or which exception it threw while its task is unfinished. */
    private static void show(String label, Supplier<Object> report) {
        try {
            System.out.println(label + ": " + report.get());
        } catch (RuntimeException e) {
            System.out.println(label + ": not working yet (" + e.getClass().getSimpleName() + ")");
        }
    }

    public static void main(String[] args) throws SQLException {
        try (Connection connection = DriverManager.getConnection(URL)) {
            List<Order> orders = OrderLoader.loadAll(connection);
            show("Loaded orders", orders::size);
            show("Needs review", () -> orders.stream().filter(OrderReports.NEEDS_REVIEW).map(Order::code).toList());
            show("Open codes", () -> OrderReports.openCodes(orders));
            show("Open summary", () -> OrderReports.openSummary(orders));
            show("Count by status", () -> OrderReports.countByStatus(orders));
            show("Cents by customer", () -> OrderReports.centsByCustomer(orders));
            show("Largest open order", () -> OrderReports.largestOpenCode(orders));
            System.out.println("Open totals above 10000 cents (from SQL): " + OrderLoader.openTotalsAbove(connection, 10000));
        }
    }
}
